const modules = [
{title:"S&OP Fundamentals",level:"Beginner",desc:"Understand the purpose, structure, and operating rhythm of integrated business planning.",topics:[
{name:"What is Sales & Operations Planning?",lectures:3,minutes:35,lessons:[
{title:"Defining S&OP",body:"<h3>One plan across the business</h3><p>Sales and Operations Planning (S&OP) is a cross-functional management process that brings together commercial, operational, and financial perspectives to create one feasible plan for the business. It connects what customers are expected to buy with what the organization can supply.</p><h3>Why organizations use it</h3><ul><li>Balance expected demand with available supply and capacity.</li><li>Expose gaps early enough for management action.</li><li>Align departments around shared assumptions and priorities.</li><li>Translate operational choices into financial consequences.</li></ul><h3>What S&OP is not</h3><p>It is not simply a forecast meeting, a production schedule, or a report prepared by one department. It is a recurring decision-making process with cross-functional ownership.</p>",connection:"The demand plan provides the expected volume. Supply planning tests whether resources can meet it. Inventory and capacity act as buffers or constraints. S&OP is the forum where trade-offs are agreed." ,question:"What is the primary purpose of S&OP?",options:["To create a production schedule for one factory","To align demand, supply, and financial plans across functions","To replace all departmental planning systems"],answer:1,explain:"Correct. S&OP aligns functions around one feasible plan and helps leaders resolve gaps."},
{title:"The objectives and business value of S&OP",body:"<h3>Core objectives</h3><p>A mature S&OP process aims to improve customer service, use resources effectively, manage inventory investment, and support profitable growth. These objectives can compete. Higher inventory may protect service but increase working capital; lower production cost may require longer campaigns and more stock.</p><h3>Business value</h3><ul><li>Better visibility of future demand and constraints.</li><li>Fewer surprises and faster escalation of material gaps.</li><li>More disciplined decisions on capacity, inventory, and priorities.</li><li>Clearer connection between operational plans and financial targets.</li></ul><h3>Measure outcomes, not meeting activity</h3><p>Attendance and slide completion do not prove S&OP effectiveness. Look at forecast performance, service, inventory health, schedule stability, and whether decisions are executed.</p>",connection:"S&OP creates a shared decision framework. KPIs later tell the organization whether those decisions improved service, cost, inventory, and plan stability.",question:"Which is a meaningful indicator of S&OP value?",options:["Number of slides presented","Improved service and inventory performance","Length of the monthly meeting"],answer:1,explain:"Correct. The process should improve measurable business outcomes, not just meeting outputs."},
{title:"S&OP versus demand and supply planning",body:"<h3>Different jobs, connected process</h3><p>Demand planning develops an unconstrained view of what customers are likely to need. Supply planning determines how the organization can respond using materials, labor, capacity, suppliers, and inventory. S&OP brings these views together, resolves gaps, and secures decisions.</p><ul><li><b>Demand planning:</b> What are customers likely to require?</li><li><b>Supply planning:</b> What can we provide, and when?</li><li><b>S&OP:</b> What plan should the business commit to, given the trade-offs?</li></ul><h3>Unconstrained versus constrained</h3><p>An unconstrained demand plan describes expected demand without limiting it to current supply. A constrained plan reflects real limits and the actions needed to close gaps. Keeping the two views visible helps decision-makers understand lost demand, required investment, or capacity needs.</p>",connection:"Demand planning feeds S&OP. Supply planning tests feasibility. S&OP decisions can then change priorities, capacity, inventory policies, or commercial commitments.",question:"Which process tests whether resources can meet expected demand?",options:["Demand planning","Supply planning","Financial closing"],answer:1,explain:"Correct. Supply planning evaluates feasibility against materials, capacity, labor, and other constraints."}
]},
{name:"The S&OP operating model",lectures:3,minutes:40,lessons:[
{title:"The five-step S&OP cycle",body:"<h3>A recurring monthly rhythm</h3><p>A common S&OP cycle includes five connected steps. Companies adapt the labels and sequence, but the intent is to move from reliable data to an agreed executive decision.</p><ul><li><b>1. Data gathering:</b> collect actuals, forecasts, inventory, capacity, and assumptions.</li><li><b>2. Demand review:</b> build and challenge the demand outlook.</li><li><b>3. Supply review:</b> test the demand plan against resources and constraints.</li><li><b>4. Pre-S&OP:</b> reconcile gaps, evaluate scenarios, and prepare recommendations.</li><li><b>5. Executive S&OP:</b> approve decisions, priorities, and actions.</li></ul><h3>Closed-loop discipline</h3><p>Actions from the executive review become inputs to the next cycle. Owners, due dates, and decision records keep the process accountable.</p>",connection:"The five steps form the operating backbone. Demand and supply planning are detailed workstreams inside the broader S&OP cycle.",question:"At which step are unresolved trade-offs typically escalated for executive decisions?",options:["Data gathering","Executive S&OP","Demand review only"],answer:1,explain:"Correct. The executive review is where leaders approve decisions and resolve escalated trade-offs."},
{title:"Roles and cross-functional ownership",body:"<h3>Shared ownership</h3><p>S&OP requires input from Sales, Marketing, Finance, Operations, Procurement, Supply Chain, and senior leadership. The exact roles depend on the organization, but each function should own the assumptions and decisions within its expertise.</p><ul><li><b>Sales / Commercial:</b> customer intelligence, promotions, pipeline, and market changes.</li><li><b>Demand planning:</b> statistical baseline, forecast consensus, and demand assumptions.</li><li><b>Operations:</b> production capability, labor, maintenance, and schedule implications.</li><li><b>Procurement:</b> supplier capacity, lead times, and material risks.</li><li><b>Finance:</b> revenue, margin, cost, and financial reconciliation.</li><li><b>Leadership:</b> priorities, risk appetite, and cross-functional trade-offs.</li></ul>",connection:"Each function supplies a different part of the same plan. Poor ownership creates conflicting assumptions and late surprises.",question:"Why should Finance participate in S&OP?",options:["To own every operational schedule","To connect operating scenarios with revenue, cost, and financial targets","To replace demand planners"],answer:1,explain:"Correct. Finance connects operational plans to business and financial outcomes."},
{title:"Governance, cadence, and decision records",body:"<h3>Make decisions repeatable</h3><p>Governance defines who prepares inputs, who challenges assumptions, who approves plans, and how exceptions are escalated. A monthly cadence is common, with weekly or daily execution processes running underneath it.</p><h3>Useful governance artifacts</h3><ul><li>Calendar and submission deadlines.</li><li>Standardized assumptions and data definitions.</li><li>Decision log with owner, due date, and status.</li><li>Escalation thresholds for material, capacity, or service risks.</li><li>Version-controlled demand and supply plans.</li></ul><p>Good governance does not mean adding meetings. It means making the right decisions at the right level with reliable information.</p>",connection:"Governance protects the integrity of the whole process. It ensures that decisions made in S&OP are translated into execution plans and reviewed later.",question:"What makes a decision log useful?",options:["It records decisions, owners, and due dates","It stores every email in the company","It replaces the operating plan"],answer:0,explain:"Correct. A decision log makes actions traceable and accountable."}
]},
{name:"S&OP maturity and implementation",lectures:2,minutes:30,lessons:[
{title:"S&OP maturity levels",body:"<h3>From reactive to integrated</h3><p>Organizations often progress from disconnected spreadsheets and reactive firefighting toward standardized, collaborative, scenario-driven planning. Maturity is not defined by software alone.</p><ul><li><b>Ad hoc:</b> fragmented data, reactive decisions, inconsistent ownership.</li><li><b>Developing:</b> recurring meetings and basic metrics, but limited integration.</li><li><b>Established:</b> standardized cycle, clear accountability, and aligned plans.</li><li><b>Advanced:</b> scenario planning, financial integration, and continuous improvement.</li></ul><p>Assess process, people, data, technology, and performance together.</p>",connection:"Maturity determines how effectively demand, supply, finance, and execution connect. It also helps prioritize improvement work.",question:"Does purchasing an advanced planning system automatically create mature S&OP?",options:["Yes, technology alone is enough","No, process, people, data, and governance matter too","Only if the system has dashboards"],answer:1,explain:"Correct. Technology supports the process but cannot replace clear ownership and disciplined decisions."},
{title:"Common implementation pitfalls",body:"<h3>Why S&OP programs struggle</h3><ul><li>Unreliable master data or inconsistent KPI definitions.</li><li>Functional teams bring different versions of the truth.</li><li>Meetings focus on reporting rather than decisions.</li><li>Forecasts are treated as commitments without understanding uncertainty.</li><li>Actions have no owners or follow-through.</li><li>Operational plans are not reconciled with financial targets.</li></ul><h3>Practical starting point</h3><p>Start with a clear business problem, define a small set of shared metrics, establish a repeatable cadence, and improve data quality incrementally. Expand complexity only when the organization can sustain it.</p>",connection:"These pitfalls often appear again in demand, supply, inventory, and KPI work. The operating model must connect all of them.",question:"What is a strong first step when implementing S&OP?",options:["Buy the most complex software available","Define the business problem, owners, and shared planning cadence","Create more reports before aligning data"],answer:1,explain:"Correct. Start with the business purpose and operating discipline before adding complexity."}
]}
]},
{title:"Demand Planning & Forecasting",level:"Beginner",desc:"Understand demand signals, forecasting methods, forecast accuracy, and consensus demand.",topics:[
{name:"Demand planning foundations",lectures:3,minutes:45,lessons:[
{title:"Demand signals and demand patterns",body:"<h3>What creates demand?</h3><p>Demand can be influenced by historical shipments, orders, customer forecasts, promotions, seasonality, pricing, market trends, and new product introductions. These signals differ in reliability and time horizon.</p><h3>Common patterns</h3><ul><li>Level: demand fluctuates around a stable average.</li><li>Trend: demand increases or decreases over time.</li><li>Seasonality: a recurring pattern tied to a calendar cycle.</li><li>Intermittent: many periods with zero demand and occasional spikes.</li></ul>",connection:"Demand patterns determine which forecasting methods are appropriate and how much uncertainty supply and inventory plans must absorb.",question:"A recurring increase in sales every December is an example of:",options:["Seasonality","Random error only","Capacity utilization"],answer:0,explain:"Correct. A repeatable calendar-linked pattern is seasonality."},
{title:"Baseline and collaborative forecasting",body:"<h3>Start with a statistical baseline</h3><p>A baseline forecast uses historical data and selected methods to estimate future demand. Commercial teams then add justified intelligence such as promotions, customer wins, losses, and market changes.</p><h3>Challenge adjustments</h3><p>Every manual adjustment should have a reason, owner, time horizon, and measurable result. Otherwise, bias can accumulate and forecast value added becomes difficult to evaluate.</p>",connection:"The demand review combines quantitative history with forward-looking business intelligence before supply feasibility is tested.",question:"What should support a manual forecast adjustment?",options:["A documented business assumption","A preference with no evidence","A desire to make the forecast larger"],answer:0,explain:"Correct. Documented assumptions allow the team to review forecast value and bias."},
{title:"Forecast horizons and aggregation",body:"<h3>Different horizons serve different decisions</h3><p>Short-term forecasts support replenishment and scheduling. Medium-term forecasts inform S&OP capacity, labor, and supplier decisions. Long-term forecasts support strategy, investment, and network design.</p><p>Forecasts can be reviewed by product, customer, location, channel, or product family. Aggregation often improves stability, but detailed execution still requires SKU-level translation.</p>",connection:"Forecast horizon and aggregation determine which supply, capacity, and financial decisions can be made with the forecast.",question:"Which horizon is most relevant to medium-term capacity decisions?",options:["Only today's orders","The medium-term planning horizon","Historical actuals only"],answer:1,explain:"Correct. Medium-term forecasts help plan labor, supplier capacity, and production resources."}
]},
{name:"Forecasting methods",lectures:3,minutes:50,lessons:[
{title:"Moving average and weighted moving average",body:"<h3>Moving average</h3><p>A simple moving average forecasts the next period using the arithmetic mean of a selected number of recent observations.</p><p><b>Formula:</b> Forecast = (sum of demand in selected periods) / number of periods.</p><h3>Weighted moving average</h3><p>A weighted moving average assigns different weights to observations, usually giving more importance to recent periods. Weights should sum to 1.00 (100%).</p><p><b>Example:</b> Demand was 100, 120, and 130 units. A three-period simple moving average is (100 + 120 + 130) / 3 = 116.7 units.</p>",connection:"The forecast becomes an input to demand consensus and then to supply, inventory, and capacity calculations.",question:"A three-period moving average uses demand of 100, 120, and 130. What is the forecast?",options:["110","116.7","130"],answer:1,explain:"Correct. (100 + 120 + 130) / 3 = 116.7 units."},
{title:"Exponential smoothing",body:"<h3>Updating a forecast</h3><p>Single exponential smoothing updates the previous forecast using the latest actual demand and a smoothing constant alpha (α).</p><p><b>Formula:</b> New forecast = α × Actual demand + (1 − α) × Previous forecast.</p><p>Alpha ranges from 0 to 1. A higher alpha responds more quickly to recent changes; a lower alpha smooths noise more heavily. This basic method is best suited to data without strong trend or seasonality.</p>",connection:"Forecast responsiveness affects the amount and timing of supply adjustments, inventory exposure, and schedule changes.",question:"A higher alpha generally makes exponential smoothing:",options:["More responsive to recent actual demand","Ignore recent demand","Always more accurate"],answer:0,explain:"Correct. A higher alpha places more weight on the latest actual."},
{title:"Forecast accuracy and bias",body:"<h3>Accuracy versus bias</h3><p>Forecast accuracy measures how close forecasts are to actual demand. Bias indicates whether forecasts consistently overestimate or underestimate demand.</p><ul><li><b>MAE:</b> mean absolute error.</li><li><b>MAPE:</b> mean absolute percentage error, with limitations when actuals are zero or very small.</li><li><b>WAPE:</b> sum of absolute errors divided by sum of actual demand.</li><li><b>Bias:</b> a signed measure of systematic over- or under-forecasting.</li></ul><p>Always define the error sign convention and aggregation level before comparing results.</p>",connection:"Forecast error is a major input to safety stock, service risk, and the amount of flexibility needed in supply planning.",question:"What does persistent positive forecast bias commonly indicate, when error is defined as forecast minus actual?",options:["Systematic over-forecasting","Systematic under-forecasting","Perfect forecast accuracy"],answer:0,explain:"Correct. Forecast minus actual above zero means the forecast is consistently higher than actual demand."}
]},
{name:"Demand review and consensus",lectures:2,minutes:30,lessons:[
{title:"Demand review meeting",body:"<h3>Purpose</h3><p>The demand review challenges the baseline forecast, incorporates commercial intelligence, documents assumptions, and agrees on a consensus demand plan.</p><p>Review major changes, forecast bias, customer events, product launches, promotions, lost business, and risks by horizon. Focus discussion on exceptions rather than reading every number.</p>",connection:"The consensus demand plan becomes the principal input to supply planning and the S&OP reconciliation process.",question:"What should a demand review focus on?",options:["Explaining every unchanged SKU","Material changes, assumptions, risks, and opportunities","Only last month's production output"],answer:1,explain:"Correct. Exception-based discussion helps teams focus on changes that may affect decisions."},
{title:"New product and end-of-life forecasting",body:"<h3>When history is missing</h3><p>New products have little or no historical demand. Forecasts may rely on analog products, market sizing, customer commitments, launch ramps, and scenario assumptions. End-of-life planning must consider final buys, remaining inventory, service obligations, and substitution to successor products.</p>",connection:"Lifecycle assumptions affect material procurement, inventory obsolescence, capacity, and financial exposure.",question:"What is a useful input when forecasting a new product with no history?",options:["An analogous product and documented launch assumptions","A random average from unrelated items","Ignoring the launch until orders arrive"],answer:0,explain:"Correct. Analog products and explicit launch assumptions provide a reasoned starting point."}
]}
]},
{title:"Supply Planning",level:"Intermediate",desc:"Translate demand into feasible supply using sourcing, production, and replenishment decisions.",topics:[
{name:"Supply planning foundations",lectures:2,minutes:35,lessons:[
{title:"Constrained supply planning",body:"<h3>Can the plan be delivered?</h3><p>Supply planning evaluates whether demand can be met within material, supplier, labor, equipment, production, logistics, and policy constraints. It identifies shortages, overloads, and timing mismatches.</p><p>A constrained plan should make limitations visible rather than hiding them inside an adjusted forecast.</p>",connection:"Supply planning tests the demand plan and surfaces gaps for S&OP decisions on priorities, capacity, inventory, or customer commitments.",question:"What is the purpose of constrained supply planning?",options:["To make demand disappear","To test feasibility against real resource constraints","To calculate sales commissions"],answer:1,explain:"Correct. It tests whether the business can meet demand with available resources."},
{title:"Sourcing and replenishment strategies",body:"<h3>How supply is fulfilled</h3><p>Supply may come from internal production, external suppliers, transfers, or a combination. Replenishment strategies include make-to-stock, make-to-order, assemble-to-order, and engineer-to-order.</p><p>Each strategy changes lead time, inventory placement, flexibility, and customer promise time.</p>",connection:"Sourcing choices affect lead time, safety stock, cost, supplier risk, and the ability to respond to demand changes.",question:"Which strategy typically starts production after a customer order?",options:["Make-to-stock","Make-to-order","Build-to-forecast only"],answer:1,explain:"Correct. Make-to-order initiates production in response to a specific customer order."}
]},
{name:"Material and supplier planning",lectures:2,minutes:35,lessons:[
{title:"Supplier lead time and reliability",body:"<h3>Lead time is more than transit</h3><p>Procurement lead time may include requisition, approval, supplier processing, manufacturing, inspection, shipment, customs, and receiving. Actual lead time can vary from the quoted value.</p><p>Supplier reliability should be evaluated using on-time delivery, quality, capacity, responsiveness, and variability.</p>",connection:"Lead-time length and variability influence planned order dates, reorder points, safety stock, and shortage exposure.",question:"Why does lead-time variability matter?",options:["It can increase uncertainty and required protection","It always reduces inventory","It has no effect if average lead time is known"],answer:0,explain:"Correct. Variability makes the timing of replenishment less predictable."},
{title:"Material requirements and shortages",body:"<h3>Dependent demand</h3><p>Component requirements are derived from planned production and the bill of materials (BOM). Material planning compares requirements with available stock, scheduled receipts, and open orders to identify net shortages.</p><p>Shortage management should quantify affected orders, dates, quantities, alternate sources, and recovery options.</p>",connection:"MRP translates production plans into component demand. Supplier constraints can then feed back into the feasible production and S&OP plan.",question:"What is the main source of dependent demand for a component?",options:["The bill of materials and planned parent production","The weather forecast","The sales team's headcount"],answer:0,explain:"Correct. Component demand is derived from parent-item production and BOM usage."}
]}
]},
{title:"Inventory Management",level:"Beginner",desc:"Learn inventory behavior, service protection, replenishment policies, and working-capital trade-offs.",topics:[
{name:"Inventory fundamentals",lectures:3,minutes:45,lessons:[
{title:"Inventory types and purpose",body:"<h3>Why inventory exists</h3><ul><li><b>Cycle stock:</b> inventory used between replenishment cycles.</li><li><b>Safety stock:</b> buffer against uncertainty in demand or supply.</li><li><b>Pipeline inventory:</b> stock moving through the supply chain.</li><li><b>Anticipation stock:</b> stock built ahead of known peaks or events.</li><li><b>Decoupling stock:</b> buffer between process stages.</li></ul><p>Inventory supports service and operational continuity but ties up cash and creates storage, handling, damage, and obsolescence risks.</p>",connection:"Inventory is the buffer between variable demand and variable supply. Its target depends on service goals, lead time, forecast uncertainty, and replenishment policy.",question:"Which inventory type protects against uncertainty?",options:["Safety stock","Pipeline inventory only","Obsolete stock"],answer:0,explain:"Correct. Safety stock provides protection against demand or supply uncertainty."},
{title:"Inventory classifications: ABC and XYZ",body:"<h3>ABC analysis</h3><p>ABC classification ranks items by annual consumption value, commonly calculated as annual demand multiplied by unit cost. A items represent high value and deserve tighter management; C items are lower value and may use simpler controls.</p><h3>XYZ analysis</h3><p>XYZ often classifies items by demand variability or predictability. Combining ABC and XYZ gives a richer policy view, such as high-value stable items versus low-value erratic items.</p>",connection:"Classification helps differentiate forecasting effort, cycle counting, service targets, and replenishment policies.",question:"ABC classification is commonly based on:",options:["Annual consumption value","Alphabetical SKU name","Supplier location"],answer:0,explain:"Correct. ABC commonly uses annual demand multiplied by unit cost."},
{title:"Inventory health and working capital",body:"<h3>Inventory is an asset with a cost</h3><p>Inventory health balances availability with investment. Excess inventory may hide forecast error, long lead times, large batch sizes, or poor coordination. Shortages can cause lost sales, production downtime, and premium freight.</p><p>Useful measures include inventory turns, days of supply, aging, excess and obsolete stock, and service level.</p>",connection:"Inventory decisions affect cash, service, production continuity, and financial performance. S&OP makes these trade-offs visible.",question:"What is a common risk of excess inventory?",options:["Higher working-capital and obsolescence exposure","Guaranteed higher forecast accuracy","Lower storage cost"],answer:0,explain:"Correct. Excess stock ties up cash and can become obsolete or incur additional holding costs."}
]},
{name:"Inventory calculations",lectures:3,minutes:55,lessons:[
{title:"Average Daily Usage and Days of Supply",body:"<h3>ADU: Average Daily Usage</h3><p>ADU estimates average consumption per day over a defined historical or forecast window.</p><p><b>Basic formula:</b> ADU = Total usage during period ÷ Number of days in period.</p><h3>DOS: Days of Supply</h3><p>DOS estimates how many days current inventory can cover at the assumed daily usage rate.</p><p><b>Formula:</b> DOS = Available inventory ÷ ADU.</p><p>Example: 2,400 units available and ADU of 120 units/day gives DOS = 20 days. Be clear whether available inventory means on-hand, net available, or includes scheduled receipts.</p>",connection:"DOS compares inventory coverage with replenishment lead time. Low coverage relative to lead time signals shortage risk.",question:"Available stock is 2,400 units and ADU is 120 units/day. What is DOS?",options:["12 days","20 days","28 days"],answer:1,explain:"Correct. 2,400 ÷ 120 = 20 days of supply."},
{title:"Safety stock and service level",body:"<h3>Purpose of safety stock</h3><p>Safety stock protects against uncertainty in demand during replenishment lead time. Higher service targets generally require more protection, but the relationship is not linear and depends on the demand and lead-time distributions.</p><p><b>Common simplified formula:</b> Safety stock = Z × σLT, where Z is the service factor and σLT is the standard deviation of demand during lead time. This assumes a suitable statistical model and should not be applied blindly.</p><p>Some organizations use demand and lead-time variability formulas. Always confirm the assumptions and service-level definition.</p>",connection:"Forecast error and lead-time variability are key drivers of safety stock. Supplier reliability and service targets influence the selected buffer.",question:"What generally happens to required safety stock when the target service level increases?",options:["It generally increases","It always becomes zero","It is unrelated to uncertainty"],answer:0,explain:"Correct. Higher service targets generally require more protection against uncertainty."},
{title:"Reorder point and inventory turns",body:"<h3>Reorder Point (ROP)</h3><p>ROP indicates when replenishment should be triggered.</p><p><b>Basic formula:</b> ROP = Demand during lead time + Safety stock.</p><p>If ADU is 100 units/day, lead time is 8 days, and safety stock is 300 units, ROP = (100 × 8) + 300 = 1,100 units.</p><h3>Inventory turnover</h3><p><b>Formula:</b> Inventory turns = Cost of goods sold ÷ Average inventory value, using consistent periods and valuation basis. Higher turns can indicate efficient inventory use, but excessively high turns may coincide with service risk.</p>",connection:"ROP combines demand rate, lead time, and safety stock. Inventory turns connect stock levels to financial performance.",question:"ADU is 100/day, lead time is 8 days, and safety stock is 300. What is ROP?",options:["800 units","1,100 units","1,300 units"],answer:1,explain:"Correct. (100 × 8) + 300 = 1,100 units."}
]},
{name:"Replenishment policies",lectures:2,minutes:30,lessons:[
{title:"Min-max and reorder point systems",body:"<h3>Continuous review</h3><p>A reorder point system monitors inventory position and triggers an order when it reaches a defined threshold. A min-max policy replenishes toward a maximum level when inventory falls to or below the minimum.</p><p>Inventory position often includes on-hand plus open orders minus backorders, but company definitions vary.</p>",connection:"Policy parameters depend on demand, lead time, order frequency, MOQ, and service goals.",question:"A reorder point system triggers replenishment when:",options:["Inventory position reaches the reorder threshold","The calendar changes month","A supplier sends an invoice"],answer:0,explain:"Correct. The reorder point is the trigger for replenishment."},
{title:"Lot sizing, MOQ, and order constraints",body:"<h3>Order quantity trade-offs</h3><p>Lot sizing determines how much to order or produce. Larger batches may reduce setup or ordering frequency but increase average inventory. Minimum Order Quantity (MOQ), pack sizes, shelf life, and supplier constraints can limit feasible quantities.</p><p>Economic Order Quantity (EOQ) is a classic model balancing ordering and holding costs under simplifying assumptions. It is a starting point, not a universal answer.</p>",connection:"Lot sizes influence cycle stock, working capital, storage, schedule stability, and the ability to respond to forecast changes.",question:"What is a common trade-off of larger order batches?",options:["Lower order frequency but higher average cycle stock","Zero inventory holding cost","No effect on production or procurement"],answer:0,explain:"Correct. Larger batches may reduce order frequency while increasing average stock."}
]}
]},
{title:"Production Planning & Capacity",level:"Intermediate",desc:"Translate supply requirements into production plans while managing finite resources and constraints.",topics:[
{name:"Production planning",lectures:2,minutes:35,lessons:[
{title:"Master Production Schedule",body:"<h3>From aggregate plan to end items</h3><p>The Master Production Schedule (MPS) states which end items are planned, in what quantities, and when. It translates higher-level plans into a more detailed production commitment that can drive material planning.</p><p>The MPS must respect demand priorities, inventory, lot sizes, lead times, and capacity feasibility.</p>",connection:"The MPS links S&OP volume decisions to detailed MRP and shop-floor execution.",question:"What does the MPS primarily specify?",options:["End items, quantities, and timing","Employee performance reviews","Annual tax obligations"],answer:0,explain:"Correct. The MPS defines planned end-item production by quantity and time."},
{title:"Production strategies and schedule stability",body:"<h3>Planning choices</h3><p>Level production maintains a relatively stable production rate and uses inventory or backlog to absorb demand variation. Chase production adjusts output to follow demand. Hybrid approaches combine stable base production with flexible capacity or overtime.</p><p>Schedule stability matters because frequent changes can create setup losses, material expedites, overtime, and quality risks.</p>",connection:"Production strategy determines how demand variability is absorbed through inventory, capacity, backlog, or schedule changes.",question:"A level production strategy generally aims to:",options:["Keep output relatively stable over time","Match output exactly to each daily demand change","Eliminate the need for inventory"],answer:0,explain:"Correct. Level production maintains a relatively stable output rate."}
]},
{name:"Capacity planning",lectures:3,minutes:45,lessons:[
{title:"Rough-cut capacity planning",body:"<h3>Test the aggregate plan</h3><p>Rough-cut capacity planning checks whether key resources can support the proposed master schedule or aggregate plan. It focuses on critical work centers, labor groups, and bottleneck equipment rather than every detailed operation.</p><p>Capacity requirements should be compared with available capacity after considering calendars, downtime, efficiency, and planned maintenance.</p>",connection:"Capacity gaps become supply constraints that may require overtime, shifts, subcontracting, investment, or demand prioritization.",question:"What is the main purpose of rough-cut capacity planning?",options:["Check key resource feasibility at an aggregate level","Calculate customer credit limits","Replace the demand forecast"],answer:0,explain:"Correct. It checks whether critical resources can support the proposed plan."},
{title:"Utilization, efficiency, and OEE",body:"<h3>Capacity measures</h3><p>Utilization compares actual or planned productive time with available time, depending on the chosen definition. Efficiency compares output or earned time with a standard. Overall Equipment Effectiveness (OEE) combines Availability × Performance × Quality.</p><p>Always document the denominator and time basis. A high utilization rate is not automatically good if it creates queues, long lead times, or no recovery capacity.</p>",connection:"Capacity measures help translate equipment and labor constraints into realistic supply plans and investment decisions.",question:"OEE is commonly calculated as:",options:["Availability × Performance × Quality","Demand × Price × Margin","Inventory ÷ Lead Time"],answer:0,explain:"Correct. OEE combines availability, performance, and quality."},
{title:"Bottlenecks and constraint management",body:"<h3>The limiting resource</h3><p>A bottleneck is a resource whose capacity constrains total system throughput. Improving a non-bottleneck may not increase system output. Constraint management focuses on protecting bottleneck time, reducing downtime and changeovers, and aligning upstream and downstream flow.</p>",connection:"Bottleneck capacity can cap the supply plan even when other work centers have unused capacity. S&OP helps prioritize scarce capacity.",question:"If one work center is the system bottleneck, which improvement is most likely to increase throughput?",options:["Increase effective capacity at the bottleneck","Increase output at an unconstrained process only","Build more work-in-process everywhere"],answer:0,explain:"Correct. Increasing effective bottleneck capacity can increase total system throughput."}
]}
]},
{title:"Material Requirements Planning (MRP)",level:"Intermediate",desc:"Understand how production plans translate into time-phased component requirements and planned orders.",topics:[
{name:"MRP fundamentals",lectures:2,minutes:35,lessons:[
{title:"BOM, gross requirements, and netting",body:"<h3>Exploding the product structure</h3><p>MRP uses the Master Production Schedule, Bill of Materials (BOM), inventory records, and planning parameters to calculate time-phased component requirements.</p><p>Gross requirements are total component needs. Net requirements account for available inventory and scheduled receipts. Planned orders propose future replenishment to cover the remaining need.</p>",connection:"The MPS translates S&OP decisions into end-item plans. MRP converts those plans into component-level material requirements.",question:"Which data structure defines component quantities needed to make a parent item?",options:["Bill of Materials","Customer satisfaction survey","Financial income statement"],answer:0,explain:"Correct. The BOM defines the product structure and component usage."},
{title:"MRP time-phasing and planned orders",body:"<h3>When to order</h3><p>MRP offsets planned receipts by procurement or manufacturing lead time to determine planned order releases. Lot-sizing rules, safety stock, calendars, and order modifiers affect the result.</p><p>MRP output is only as reliable as its inputs. Incorrect inventory balances, BOMs, lead times, or order policies can create misleading recommendations.</p>",connection:"MRP converts a feasible production plan into actionable procurement and production proposals, which can reveal new supply constraints.",question:"Why does MRP offset planned receipts by lead time?",options:["To calculate when an order must be released","To increase the sales forecast","To remove the BOM"],answer:0,explain:"Correct. Lead-time offset determines the release date needed to receive material on time."}
]},
{name:"MRP controls and exceptions",lectures:2,minutes:30,lessons:[
{title:"MRP exception messages",body:"<h3>Manage by exception</h3><p>MRP exception messages may indicate expedite, defer, cancel, reschedule, or shortage conditions. Planners should evaluate whether the message is actionable, considering supplier reality, frozen zones, order status, and downstream impact.</p>",connection:"Exceptions highlight mismatches between the plan and current conditions. Material risks should be escalated into supply review and S&OP when they affect service or capacity.",question:"An expedite message usually suggests:",options:["A receipt may be needed earlier than currently planned","Demand should always be deleted","The supplier has delivered early"],answer:0,explain:"Correct. It signals a potential need to accelerate a planned receipt."},
{title:"Data integrity and planning parameters",body:"<h3>Control the inputs</h3><p>Important planning data includes BOM accuracy, on-hand inventory, open purchase orders, lead times, lot sizes, safety stock, calendars, and sourcing rules. Cycle counting, parameter ownership, and regular exception review help maintain integrity.</p>",connection:"Master data quality is foundational. Poor data can distort inventory, capacity, and supply recommendations across the entire S&OP system.",question:"Which is an example of a planning master-data parameter?",options:["Procurement lead time","Today's meeting attendance","A one-time presentation title"],answer:0,explain:"Correct. Procurement lead time is a planning parameter that affects order timing."}
]}
]},
{title:"Sales, Operations & Financial Alignment",level:"Advanced",desc:"Reconcile operational choices with revenue, margin, cost, and strategic business priorities.",topics:[
{name:"Financial integration",lectures:2,minutes:35,lessons:[
{title:"Operational plan to financial plan",body:"<h3>Translate volume into value</h3><p>Operational plans become financially meaningful when volume, mix, price, yield, labor, material cost, freight, and inventory are translated into revenue, margin, cost, and cash implications.</p><p>Finance should reconcile the S&OP plan with budgets and targets, explaining gaps and assumptions rather than forcing the operational plan to match a number without a feasible path.</p>",connection:"Financial integration makes trade-offs visible: overtime versus outsourcing, inventory versus service, or capacity investment versus lost sales.",question:"Why should the operational plan be reconciled with the financial plan?",options:["To understand financial consequences of operating decisions","To make production independent of demand","To remove all assumptions"],answer:0,explain:"Correct. The reconciliation connects operating choices with financial outcomes."},
{title:"Revenue, margin, and product mix",body:"<h3>Volume is not the whole story</h3><p>Two plans with the same total volume can produce different revenue and margin because of product mix, customer mix, price, and variable cost. S&OP should examine mix shifts, constraints on high-margin products, and the implications of customer priorities.</p>",connection:"Demand mix changes the material, labor, and capacity profile. Supply decisions can therefore alter revenue and margin, not just total units.",question:"Why can two plans with equal total volume have different margin?",options:["They may have different product and customer mix","Volume always determines margin exactly","Inventory has no financial effect"],answer:0,explain:"Correct. Product and customer mix, price, and cost structure affect margin."}
]},
{name:"Trade-offs and decision analysis",lectures:2,minutes:35,lessons:[
{title:"Service, cost, and working-capital trade-offs",body:"<h3>No single metric tells the whole story</h3><p>Increasing inventory may improve availability but consume cash. Running larger batches may reduce setup cost but increase stock and obsolescence. Overtime may protect service but raise conversion cost. S&OP provides a structured place to compare these trade-offs.</p>",connection:"This is where demand, supply, inventory, capacity, and finance converge into management decisions.",question:"Which statement best describes an S&OP trade-off?",options:["A decision that balances competing business objectives","A metric that never changes","A forecast with no uncertainty"],answer:0,explain:"Correct. Trade-offs balance competing objectives such as service, cost, and cash."},
{title:"Executive decision framing",body:"<h3>Bring options, not just problems</h3><p>A decision-ready recommendation states the issue, impact, options, assumptions, risks, financial effect, preferred choice, and decision owner. Scenario comparisons help leaders understand consequences before committing.</p>",connection:"Executive S&OP turns cross-functional analysis into clear choices, owners, and follow-through.",question:"A decision-ready escalation should include:",options:["Impact, options, assumptions, and a recommendation","Only a screenshot of the problem","A list of unrelated historical data"],answer:0,explain:"Correct. Leaders need clear options and consequences to make a decision."}
]}
]},
{title:"S&OP Metrics & KPIs",level:"Intermediate",desc:"Measure forecast performance, customer service, inventory, schedule execution, and process effectiveness.",topics:[
{name:"Demand and service KPIs",lectures:2,minutes:35,lessons:[
{title:"Forecast accuracy and forecast bias",body:"<h3>Measure forecast quality consistently</h3><p>Forecast accuracy compares forecasts with actual demand using a defined error measure and horizon. Forecast bias indicates the direction of systematic error. Metrics should be calculated at a level that matches the decision and should avoid misleading aggregation.</p><p>MAPE can be undefined or unstable when actual demand is zero or very small. WAPE is often more stable for aggregation but can hide item-level problems.</p>",connection:"Forecast performance informs inventory buffers, supply flexibility, and the credibility of demand assumptions.",question:"Which metric indicates the direction of systematic forecast error?",options:["Forecast bias","Inventory turns","OEE"],answer:0,explain:"Correct. Bias shows whether forecasts systematically over- or under-estimate actual demand."},
{title:"OTIF, fill rate, and customer service",body:"<h3>Service has multiple definitions</h3><p>On Time In Full (OTIF) measures orders delivered by the requested or committed date and in the required quantity, according to the organization's definition. Fill rate measures the portion of demand fulfilled from available stock or supply. Perfect order measures may include additional conditions such as damage-free and accurate documentation.</p>",connection:"Service KPIs reveal whether the demand and supply plan is delivering the customer outcome the business expects.",question:"OTIF commonly evaluates whether an order is:",options:["On time and in full","Over forecast and in transit","Only fully invoiced"],answer:0,explain:"Correct. OTIF combines timeliness and quantity completeness."}
]},
{name:"Supply and inventory KPIs",lectures:2,minutes:35,lessons:[
{title:"Inventory turns, DOS, and aging",body:"<h3>Use complementary measures</h3><p>Inventory turns measure how frequently average inventory is consumed or sold over a period. Days of Supply estimates coverage at a given usage rate. Aging shows how long stock has remained in inventory. Together they reveal velocity, coverage, and potential obsolescence.</p>",connection:"These measures help balance service protection with working-capital and obsolescence risk.",question:"Which metric estimates how many days current stock can cover?",options:["Days of Supply","Forecast bias","OTIF"],answer:0,explain:"Correct. DOS estimates coverage based on available inventory and usage rate."},
{title:"Schedule adherence and OEE",body:"<h3>Execution performance</h3><p>Schedule adherence measures how closely production follows the agreed schedule, using a clearly defined numerator and denominator. OEE combines availability, performance, and quality to assess equipment effectiveness.</p><p>High schedule adherence supports material and delivery reliability, while OEE helps identify equipment losses. Neither metric should be optimized without considering the whole flow.</p>",connection:"Execution KPIs feed back into supply planning assumptions, capacity models, and the next S&OP cycle.",question:"What does OEE combine?",options:["Availability, performance, and quality","Sales, margin, and price","ADU, DOS, and ROP"],answer:0,explain:"Correct. OEE combines availability, performance, and quality."}
]}
]},
{title:"Advanced S&OP & Scenario Planning",level:"Advanced",desc:"Manage uncertainty with scenarios, constraints, risk analysis, and robust decision-making.",topics:[
{name:"Scenario planning",lectures:2,minutes:35,lessons:[
{title:"What-if analysis and scenarios",body:"<h3>Explore plausible futures</h3><p>Scenario planning evaluates how different assumptions affect demand, supply, service, cost, and financial outcomes. Scenarios may include upside demand, downside demand, supplier disruption, capacity loss, or price changes.</p><p>A good scenario changes a defined assumption, measures the consequences, and identifies the decision trigger or action required.</p>",connection:"Scenarios connect uncertain demand and supply conditions to management choices before a disruption becomes an emergency.",question:"What makes a what-if scenario useful?",options:["It links changed assumptions to measurable consequences and actions","It changes many inputs without documenting them","It guarantees the future"],answer:0,explain:"Correct. Scenarios are useful when assumptions, impacts, and actions are explicit."},
{title:"Risk, opportunity, and contingency planning",body:"<h3>Prepare before the trigger</h3><p>Risk planning identifies potential events, likelihood, impact, early-warning indicators, owners, and mitigation actions. Opportunity planning identifies upside demand or cost opportunities and the capacity or material needed to capture them.</p><p>Contingency plans should define triggers, response options, decision rights, and communication paths.</p>",connection:"Risk and opportunity management gives S&OP a forward-looking view of threats and upside beyond the baseline plan.",question:"A useful contingency plan should define:",options:["Triggers, owners, and response actions","Only the event name","A target with no response"],answer:0,explain:"Correct. Contingency plans need triggers, accountability, and actions."}
]},
{name:"Constraint and allocation decisions",lectures:2,minutes:35,lessons:[
{title:"Demand prioritization under shortage",body:"<h3>Allocate scarce supply deliberately</h3><p>When supply cannot meet all demand, allocation rules may consider customer commitments, contractual obligations, strategic accounts, margin, product criticality, and fairness. The rules should be transparent and approved at the right level.</p>",connection:"Allocation decisions connect constrained supply with customer service, revenue, margin, and strategic priorities.",question:"Why should shortage allocation rules be agreed in advance?",options:["To make prioritization transparent and consistent","To avoid communicating with customers","To maximize random allocation"],answer:0,explain:"Correct. Agreed rules reduce ad hoc decisions and align actions with business priorities."},
{title:"Capacity and network scenarios",body:"<h3>Evaluate structural choices</h3><p>Capacity scenarios may compare overtime, additional shifts, subcontracting, equipment investment, alternate sites, or demand shaping. Evaluate ramp-up time, cost, quality, logistics, and reversibility rather than comparing nameplate capacity alone.</p>",connection:"Network and capacity decisions may have long lead times, so long-range demand and financial scenarios should inform them.",question:"Which factor should be considered when comparing capacity options?",options:["Ramp-up time, cost, quality, and flexibility","Only theoretical maximum output","Only the purchase price"],answer:0,explain:"Correct. Capacity options must be compared using practical and financial implications."}
]}
]},
{title:"S&OP Systems, Tools & Business Applications",level:"Intermediate",desc:"Understand planning data, spreadsheets, analytics, ERP, and planning-system capabilities.",topics:[
{name:"Data and systems foundations",lectures:2,minutes:30,lessons:[
{title:"ERP, APS, and planning data",body:"<h3>Different systems, connected information</h3><p>ERP systems commonly manage transactions such as orders, inventory, purchasing, and production records. Advanced Planning Systems (APS) support planning optimization, forecasting, and scenario analysis. Data warehouses and analytics platforms consolidate information for reporting.</p><p>System architecture varies by organization. Clear master data, ownership, and integration rules are more important than tool labels.</p>",connection:"Systems provide the data and planning capabilities used by demand, supply, inventory, and financial workstreams.",question:"Which system category commonly supports advanced planning and optimization?",options:["APS","Email client","Presentation software"],answer:0,explain:"Correct. APS tools commonly support planning, optimization, and scenario analysis."},
{title:"Master data and data quality",body:"<h3>Trust the inputs</h3><p>Planning depends on accurate product, customer, location, BOM, sourcing, lead-time, calendar, and inventory data. Data quality dimensions include accuracy, completeness, consistency, timeliness, and uniqueness.</p><p>Define a system of record, data owner, validation rules, and correction process for critical fields.</p>",connection:"Data quality affects forecast aggregation, MRP, capacity calculations, inventory policy, and KPI credibility.",question:"Which is a data quality dimension?",options:["Completeness","Slide animation","Meeting duration"],answer:0,explain:"Correct. Completeness measures whether required data is present."}
]},
{name:"Analytics and decision support",lectures:2,minutes:35,lessons:[
{title:"Excel and BI for S&OP",body:"<h3>Use tools to answer planning questions</h3><p>Spreadsheets are useful for controlled analysis, calculations, and scenario prototypes. Business Intelligence tools help consolidate data, visualize trends, and monitor KPIs. Strong models document assumptions, units, time periods, filters, and refresh timing.</p><p>Automate repeatable data preparation where possible, but retain validation checks and traceability.</p>",connection:"Analytics makes the links between demand, inventory, capacity, and service visible to planners and decision-makers.",question:"What should a reliable planning dashboard make clear?",options:["Metric definitions, time period, filters, and data freshness","Only colors and chart styles","A number without units or context"],answer:0,explain:"Correct. Clear definitions and context are essential for trustworthy decisions."},
{title:"Planning models and scenario tools",body:"<h3>Model the decision</h3><p>A planning model should identify inputs, assumptions, constraints, outputs, and validation checks. Sensitivity analysis shows how outputs change when key assumptions vary. Scenario tools should preserve the baseline and make scenario differences traceable.</p>",connection:"Planning models allow teams to compare options consistently and carry selected assumptions into the S&OP decision process.",question:"Why preserve a baseline when running scenarios?",options:["To compare changes against a consistent reference","To prevent any scenario changes","To hide assumptions"],answer:0,explain:"Correct. A baseline provides a consistent reference for evaluating scenario impact."}
]}
]},
{title:"Integrated Business Planning (IBP)",level:"Advanced",desc:"Extend S&OP into a broader strategic and financial planning process.",topics:[
{name:"IBP foundations",lectures:2,minutes:35,lessons:[
{title:"S&OP and IBP",body:"<h3>From operational alignment to enterprise integration</h3><p>Integrated Business Planning (IBP) is often used to describe a more mature process that connects operational plans with financial plans and strategic objectives over a broader horizon. Terminology varies across organizations and vendors.</p><p>IBP does not replace S&OP fundamentals. It extends integration, financial reconciliation, portfolio decisions, and strategic scenario planning.</p>",connection:"IBP builds on S&OP by connecting demand, supply, product, finance, and strategy in one integrated planning framework.",question:"IBP is commonly understood as:",options:["A broader integration of operational, financial, and strategic planning","A daily production dispatch list","A replacement for all business functions"],answer:0,explain:"Correct. IBP extends cross-functional planning into financial and strategic alignment."},
{title:"Portfolio and product lifecycle integration",body:"<h3>Plan the product portfolio</h3><p>Portfolio planning considers launches, growth, maturity, decline, and discontinuation. Decisions about product mix, lifecycle timing, and resource allocation affect demand, materials, capacity, inventory, and financial outcomes.</p>",connection:"Portfolio choices change the shape of future demand and the resources required to serve it.",question:"Why should product lifecycle decisions be part of integrated planning?",options:["They affect future demand, supply, inventory, and financial outcomes","They only affect marketing artwork","They have no impact on operations"],answer:0,explain:"Correct. Product lifecycle decisions affect the entire operating and financial plan."}
]},
{name:"Strategic and financial integration",lectures:2,minutes:35,lessons:[
{title:"Long-range planning and strategic alignment",body:"<h3>Connect today's plan with tomorrow's capabilities</h3><p>Long-range planning examines demand growth, market shifts, network capacity, technology, supplier strategy, and investment requirements. It uses scenarios to test whether the organization can support its strategic direction.</p>",connection:"Long-range plans inform capacity investment, sourcing strategy, product portfolio choices, and financial targets.",question:"Which decision is most likely to require long-range planning?",options:["Building a new production facility","Expediting a single purchase order","Changing tomorrow's shift roster"],answer:0,explain:"Correct. Facility investment has long lead times and strategic implications."},
{title:"IBP performance and continuous improvement",body:"<h3>Improve the planning system</h3><p>Continuous improvement reviews forecast quality, service, inventory, plan adherence, decision cycle time, and financial alignment. The goal is not simply to increase the number of metrics, but to improve the quality and speed of decisions.</p>",connection:"Performance feedback closes the loop between strategy, integrated plans, execution, and the next planning cycle.",question:"What is the purpose of continuous improvement in IBP?",options:["Improve planning decisions and business outcomes over time","Add more reports regardless of value","Avoid reviewing assumptions"],answer:0,explain:"Correct. Improvement should strengthen the planning process and its outcomes."}
]}
]},
{title:"Practical S&OP Case Studies",level:"Advanced",desc:"Apply the concepts to realistic planning situations and communicate decision recommendations.",topics:[
{name:"Integrated planning exercises",lectures:2,minutes:45,lessons:[
{title:"Case study: Demand spike with constrained capacity",body:"<h3>Scenario</h3><p>Demand for a product family is forecast to increase 18% next quarter. The main production line is already planned at 92% of available capacity. A critical component has a 10-week supplier lead time.</p><h3>Analysis path</h3><ul><li>Validate the demand signal and identify customer / SKU mix.</li><li>Calculate the capacity gap by period and bottleneck.</li><li>Check component coverage, open orders, and supplier flexibility.</li><li>Build options: overtime, alternate sourcing, subcontracting, or allocation.</li><li>Quantify service, cost, inventory, and margin implications.</li></ul><h3>Decision output</h3><p>Prepare a recommendation with assumptions, timing, risks, trigger points, and owners. Do not assume a single option solves every constraint.</p>",connection:"This case connects demand forecasting, capacity planning, supplier lead time, inventory, financial trade-offs, and executive decisions.",question:"What should be checked before committing to the 18% demand increase?",options:["Demand validity, component availability, and capacity feasibility","Only the total annual sales number","Only last month's inventory turns"],answer:0,explain:"Correct. Demand, material, and capacity feasibility must be assessed together."},
{title:"Case study: Excess inventory and weak forecast accuracy",body:"<h3>Scenario</h3><p>A product family has 75 days of supply, forecast accuracy has declined, and several SKUs show no movement for 90 days. Sales reports a changing customer mix.</p><h3>Analysis path</h3><ul><li>Segment inventory by value, age, and demand variability.</li><li>Compare forecast bias and actual consumption by SKU.</li><li>Review MOQ, lot size, lead time, and replenishment settings.</li><li>Identify obsolete, excess, and potentially transferable stock.</li><li>Agree actions to prevent recurrence and quantify cash impact.</li></ul>",connection:"This case combines demand quality, ABC/XYZ, DOS, lot sizing, inventory aging, and financial impact.",question:"Which is the strongest first analysis step?",options:["Segment inventory by value, age, and demand behavior","Immediately increase all safety stock","Ignore forecast bias"],answer:0,explain:"Correct. Segmentation identifies where the exposure is concentrated and what is driving it."}
]},
{name:"Communication and decision practice",lectures:2,minutes:35,lessons:[
{title:"Building an executive S&OP recommendation",body:"<h3>A concise decision narrative</h3><p>Structure an executive recommendation around: situation, gap, business impact, options, assumptions, recommendation, decision required, owner, and timing. Use a small number of decision-relevant visuals rather than a data dump.</p><p>Separate facts from assumptions and clearly state what happens if no decision is made.</p>",connection:"The quality of S&OP depends not only on analysis but on translating it into clear choices and accountable actions.",question:"What should an executive recommendation explicitly state?",options:["The decision required and its business impact","Every raw data row","Only the analyst's preferred chart"],answer:0,explain:"Correct. Leaders need to know what decision is needed and what it means."},
{title:"Planner problem-solving framework",body:"<h3>Think from signal to action</h3><p>When a planning exception appears, define the problem, validate the data, identify the driver, quantify the impact, generate feasible options, evaluate trade-offs, recommend an action, and monitor the result.</p><p>Record what changed and what was learned so future assumptions and planning parameters can improve.</p>",connection:"This framework can be used across demand, supply, inventory, capacity, and financial planning.",question:"What should happen after an action is implemented?",options:["Monitor the result and update assumptions if needed","Close the issue without checking","Delete the original baseline"],answer:0,explain:"Correct. Monitoring closes the loop and creates learning for the next planning cycle."}
]}
]}
];

const glossary = [
["ADU","Average Daily Usage","Average quantity consumed per day over a defined period.","Inventory"],
["APS","Advanced Planning System","Software that supports planning, optimization, and scenario analysis.","Systems"],
["ATP","Available to Promise","Uncommitted inventory and/or planned supply that can be promised to customers.","Order fulfillment"],
["ABC Analysis","ABC Classification","Inventory segmentation based on annual consumption value, commonly A, B, and C classes.","Inventory"],
["BOM","Bill of Materials","A structured list of components and quantities required to make a product.","Manufacturing"],
["CTP","Capable to Promise","A customer promise based on checking material and capacity availability.","Order fulfillment"],
["DOS","Days of Supply","Estimated number of days current available inventory can cover at a given usage rate.","Inventory"],
["EOQ","Economic Order Quantity","A calculated order size that balances ordering and holding costs under defined assumptions.","Inventory"],
["ERP","Enterprise Resource Planning","An integrated system for core business transactions and records.","Systems"],
["IBP","Integrated Business Planning","An integrated planning approach connecting operations, finance, and strategy.","S&OP"],
["KPI","Key Performance Indicator","A defined measure used to monitor performance against an objective.","Performance"],
["LT","Lead Time","Elapsed time between initiating a process or order and receiving its output.","Supply"],
["MAPE","Mean Absolute Percentage Error","Average absolute forecast error expressed as a percentage of actual demand; problematic with zero actuals.","Forecasting"],
["MPS","Master Production Schedule","A time-phased plan of end items, quantities, and production timing.","Manufacturing"],
["MRP","Material Requirements Planning","A method that calculates time-phased material requirements from production plans and product structures.","Supply"],
["MOQ","Minimum Order Quantity","The smallest quantity a supplier or process allows for an order.","Procurement"],
["OEE","Overall Equipment Effectiveness","A measure combining equipment availability, performance, and quality.","Manufacturing"],
["OTIF","On Time In Full","A customer-service measure checking whether orders arrive on time and in the required quantity.","Performance"],
["ROP","Reorder Point","The inventory position that triggers replenishment, often demand during lead time plus safety stock.","Inventory"],
["S&OP","Sales & Operations Planning","A cross-functional process aligning demand, supply, and financial plans.","S&OP"],
["SKU","Stock Keeping Unit","A distinct item or product variant tracked in inventory and planning.","Inventory"],
["SS","Safety Stock","Inventory held as protection against demand or supply uncertainty.","Inventory"],
["WAPE","Weighted Absolute Percentage Error","Sum of absolute forecast errors divided by sum of actual demand, often used for aggregate accuracy.","Forecasting"],
["XYZ Analysis","Demand Variability Classification","A way to classify items by demand variability or predictability; definitions vary by organization.","Inventory"]
];

const conceptInfo = {
"S&OP":{type:"CORE PROCESS",title:"Sales & Operations Planning",desc:"A cross-functional business planning process that aligns demand, supply, and financial plans into one achievable operating plan.",why:"It creates one agreed plan so teams can make coordinated trade-offs instead of optimizing in silos.",related:["Demand Planning","Supply Planning","Inventory Management","Financial Planning"]},
"Demand Planning":{type:"COMMERCIAL INPUT",title:"Demand Planning",desc:"The process of estimating future customer demand using historical patterns, statistical forecasts, and commercial intelligence.",why:"A credible demand view helps the organization prepare materials, capacity, inventory, and customer commitments.",related:["S&OP","Forecasting","Inventory Management","Financial Planning"]},
"Supply Planning":{type:"OPERATIONS INPUT",title:"Supply Planning",desc:"The process of determining how demand can be met using available materials, suppliers, labor, capacity, and inventory.",why:"It tests feasibility and exposes constraints that need operational or management action.",related:["S&OP","Production Planning","Capacity Planning","Inventory Management"]},
"Production Planning":{type:"EXECUTION",title:"Production Planning",desc:"The process of deciding what to produce, how much, and when, considering demand, resources, materials, and operational policies.",why:"It translates the agreed supply plan into a sequence and volume of production activity.",related:["Supply Planning","Capacity Planning","MRP","Inventory Management"]},
"Inventory Management":{type:"BUFFER",title:"Inventory Management",desc:"The discipline of setting and controlling stock to balance availability, service, cost, and working capital.",why:"Inventory absorbs timing and variability differences between demand and supply, but too much stock creates financial and obsolescence risk.",related:["Demand Planning","Supply Planning","Lead Time","Safety Stock"]},
"Capacity Planning":{type:"CONSTRAINT",title:"Capacity Planning",desc:"The process of comparing required workload with available equipment, labor, and other constrained resources.",why:"Capacity determines whether the supply plan is achievable and what alternatives are needed when resources are overloaded.",related:["Supply Planning","Production Planning","S&OP","OEE"]},
"Financial Planning":{type:"BUSINESS IMPACT",title:"Financial Planning",desc:"The translation of volume, mix, price, cost, and inventory assumptions into revenue, margin, expense, and cash outcomes.",why:"It helps decision-makers understand the financial consequences of operating choices and align plans with business targets.",related:["S&OP","Demand Planning","Inventory Management","Performance KPIs"]},
"Performance KPIs":{type:"FEEDBACK",title:"Performance KPIs",desc:"Measures that show whether the plan and its execution are delivering expected outcomes.",why:"Performance feedback reveals gaps and helps improve future forecasts, supply assumptions, inventory policies, and decisions.",related:["S&OP","Demand Planning","Supply Planning","Financial Planning"]}
};

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
let completed = new Set(JSON.parse(localStorage.getItem("sopAcademyCompleted") || "[]"));
let currentLesson = null;
let currentModule = 0;

function totalTopics(){return modules.reduce((n,m)=>n+m.topics.length,0)}
function completedCount(){return completed.size}
function updateProgress(){
 const pct=Math.round(completedCount()/totalTopics()*100);
 $("#progressPercent").innerHTML=pct+'<small>%</small>';$("#progressBar").style.width=pct+"%";
 $("#completedLabel").textContent=completedCount()+" of "+totalTopics()+" topics completed";
 $("#progressBig").textContent=pct+"%";$("#ringValue").textContent=pct+"%";
 $("#progressRing").style.background="conic-gradient(#5b9a91 "+(pct*3.6)+"deg,#e9eff0 0deg)";
 $("#progressDescription").textContent=pct===0?"Your learning journey starts here.":pct===100?"Curriculum completed. Keep revisiting and applying your knowledge.":completedCount()+" topics completed. Keep building your S&OP foundation.";
}
function showView(name){
 $$(".view").forEach(v=>v.classList.toggle("active",v.id==="view-"+name));
 $$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===name));
 $("#crumbCurrent").textContent=({dashboard:"Overview",modules:"Learning modules",concepts:"Concept map",glossary:"Technical glossary",progress:"My progress"})[name];
 $("#sidebar").classList.remove("open");window.scrollTo({top:0,behavior:"smooth"});
 if(name==="progress")renderProgress();
}
$$(".nav-item").forEach(b=>b.addEventListener("click",()=>showView(b.dataset.view)));
$$("[data-go]").forEach(b=>b.addEventListener("click",()=>showView(b.dataset.go)));
$("#menuToggle").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));

function renderModules(){
 const q=($("#moduleSearch")?.value||"").toLowerCase(),level=$("#levelFilter")?.value||"all";
 const root=$("#moduleList");root.innerHTML="";
 modules.forEach((m,i)=>{
  const matches=m.title.toLowerCase().includes(q)||m.desc.toLowerCase().includes(q)||m.topics.some(t=>t.name.toLowerCase().includes(q));
  if(!matches||(level!=="all"&&m.level!==level))return;
  const done=m.topics.filter((t,j)=>completed.has(i+"-"+j)).length,pct=Math.round(done/m.topics.length*100);
  const card=document.createElement("article");card.className="module-card"+(i===0?" open":"");
  card.innerHTML='<button class="module-head"><span class="module-number">'+String(i+1).padStart(2,"0")+'</span><span class="module-info"><span class="eyebrow">'+m.level.toUpperCase()+' · MODULE '+String(i+1).padStart(2,"0")+'</span><strong>'+m.title+'</strong><small>'+m.topics.length+' topics · '+m.desc+'</small></span><span class="module-progress">'+done+'/'+m.topics.length+'<i><b style="width:'+pct+'%"></b></i></span><span class="module-chevron">⌄</span></button><div class="module-topics">'+m.topics.map((t,j)=>'<div class="topic-row"><span class="topic-check '+(completed.has(i+"-"+j)?"done":"")+'">'+(completed.has(i+"-"+j)?"✓":"")+'</span><span class="topic-text"><strong>'+t.name+'</strong><small>'+t.lectures+' lectures · '+t.minutes+' min</small></span><button data-topic="'+i+'-'+j+'">Open topic →</button></div>').join("")+'</div>';
  card.querySelector(".module-head").addEventListener("click",()=>card.classList.toggle("open"));
  card.querySelectorAll("[data-topic]").forEach(btn=>btn.addEventListener("click",()=>openLesson(i,Number(btn.dataset.topic.split("-")[1]),0)));
  root.appendChild(card);
 });
 if(!root.children.length)root.innerHTML='<div class="empty-state">No modules match your search.</div>';
}
$("#moduleSearch").addEventListener("input",renderModules);$("#levelFilter").addEventListener("change",renderModules);
$$("[data-open-module]").forEach(b=>b.addEventListener("click",()=>{showView("modules");renderModules();const first=$(".module-card");if(first)first.classList.add("open")}));

function openLesson(mi,ti,li){
 currentModule=mi;const topic=modules[mi].topics[ti],lesson=topic.lessons[li];currentLesson={mi,ti,li};
 $("#lessonModule").textContent="MODULE "+String(mi+1).padStart(2,"0")+" · "+modules[mi].title;
 $("#lessonTopic").textContent="TOPIC "+(mi+1)+"."+ (ti+1)+" · LECTURE "+(li+1)+" OF "+topic.lessons.length;
 $("#lessonTitle").textContent=lesson.title;$("#lessonMeta").textContent="GUIDED LECTURE · "+Math.max(8,Math.round(topic.minutes/topic.lectures))+" MIN READ";
 $("#lessonBody").innerHTML=lesson.body;$("#lessonConnection").textContent=lesson.connection;
 $("#quizQuestion").textContent=lesson.question;$("#quizFeedback").textContent="";
 $("#quizOptions").innerHTML=lesson.options.map((o,i)=>'<button class="quiz-option" data-answer="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("");
 $("#quizOptions").querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{
  const chosen=Number(b.dataset.answer);$$(".quiz-option").forEach(x=>{x.disabled=true;if(Number(x.dataset.answer)===lesson.answer)x.classList.add("correct")});
  if(chosen!==lesson.answer)b.classList.add("wrong");
  $("#quizFeedback").textContent=(chosen===lesson.answer?"Correct. ":"Not quite. ")+lesson.explain;
 }));
 const isDone=completed.has(mi+"-"+ti);$("#lessonStatus").textContent=isDone?"Topic completed ✓":"Not completed";$("#lessonStatus").classList.toggle("complete",isDone);
 $("#completeLesson").textContent=isDone?"Completed ✓":"Mark topic complete ✓";
 $("#lessonModal").classList.add("open");$("#lessonModal").setAttribute("aria-hidden","false");
}
function closeLesson(){$("#lessonModal").classList.remove("open");$("#lessonModal").setAttribute("aria-hidden","true")}
$("#closeLesson").addEventListener("click",closeLesson);$("#lessonModal").addEventListener("click",e=>{if(e.target.id==="lessonModal")closeLesson()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeLesson()});
$("#completeLesson").addEventListener("click",()=>{
 if(!currentLesson)return;const key=currentLesson.mi+"-"+currentLesson.ti;
 if(!completed.has(key)){completed.add(key);localStorage.setItem("sopAcademyCompleted",JSON.stringify([...completed]));}
 $("#lessonStatus").textContent="Topic completed ✓";$("#lessonStatus").classList.add("complete");$("#completeLesson").textContent="Completed ✓";
 updateProgress();renderModules();
});

function renderGlossary(){
 const q=($("#glossarySearch").value||"").toLowerCase(),letter=$(".letter-filter button.active")?.dataset.letter||"all";
 const list=glossary.filter(t=>(letter==="all"||t[0].toUpperCase().startsWith(letter))&&t.join(" ").toLowerCase().includes(q));
 $("#glossaryCount").textContent=list.length+" TERMS";
 $("#glossaryGrid").innerHTML=list.map(t=>'<article class="term-card"><span class="term-acronym">'+t[0]+'</span><h3>'+t[1]+'</h3><p>'+t[2]+'</p><span class="term-category">'+t[3].toUpperCase()+'</span></article>').join("")||'<div class="empty-state">No terms found. Try another search.</div>';
}
$("#glossarySearch").addEventListener("input",renderGlossary);
$("#letterFilter").querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{$$(".letter-filter button").forEach(x=>x.classList.remove("active"));b.classList.add("active");renderGlossary()}));

function renderConcept(name){
 const c=conceptInfo[name];if(!c)return;
 $$(".map-node").forEach(n=>n.classList.toggle("selected",n.dataset.concept===name));
 $("#conceptDetail").innerHTML='<div class="eyebrow">SELECTED CONCEPT</div><span class="detail-chip">'+c.type+'</span><h2>'+c.title+'</h2><p>'+c.desc+'</p><div class="detail-section"><strong>Why it matters</strong><p>'+c.why+'</p></div><div class="detail-section"><strong>Related concepts</strong><div class="related-tags">'+c.related.map(x=>'<span>'+x+'</span>').join("")+'</div></div>';
}
$$(".map-node").forEach(n=>n.addEventListener("click",()=>renderConcept(n.dataset.concept)));
$("#resetMap").addEventListener("click",()=>renderConcept("S&OP"));

function renderProgress(){
 const root=$("#progressModules");root.innerHTML=modules.map((m,i)=>{
  const done=m.topics.filter((t,j)=>completed.has(i+"-"+j)).length,pct=Math.round(done/m.topics.length*100);
  return '<article class="progress-module"><div class="progress-module-head"><strong>'+String(i+1).padStart(2,"0")+' · '+m.title+'</strong><small>'+done+'/'+m.topics.length+'</small></div><div class="progress-track"><i style="width:'+pct+'%"></i></div></article>';
 }).join("");
}
updateProgress();renderModules();renderGlossary();renderProgress();